cat > src/remind.sh <<'EOF'
#!/bin/bash
# remind.sh [--who NAME] DATE: one reminder per booking of the day (only NAME's with --who), from the listing.
set -u
usage() { echo "usage: remind.sh [--who NAME] DATE" >&2; exit 2; }
who=
if [ "${1:-}" = --who ]; then [ $# -ge 2 ] && [ -n "$2" ] || usage; who=$2; shift 2; fi
[ $# -eq 1 ] || usage
out=$(bash "$(dirname "$0")/list.sh" "$1") || exit $?
[ -z "$out" ] || printf '%s\n' "$out" | awk -v w="$who" 'w == "" || $4 == w' | while read -r d t r w; do echo "reminder to $w: $r $d $t"; done
EOF
cat > spec/remind_who.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tsato\nkaede\t2026-01-01\t13:00\t14:00\tito\nsakura\t2026-01-01\t15:00\t16:00\tsatoh\n' > "$t"
[ "$(BOOKINGS=$t bash src/remind.sh --who sato 2026-01-01)" = 'reminder to sato: aoi 2026-01-01 10:00-11:00' ] || { echo "remind --who"; fail=1; }
bash src/remind.sh >/dev/null 2>&1; [ $? = 2 ] || { echo "no date should exit 2"; fail=1; }
[ "$(BOOKINGS=$t bash src/remind.sh --who sato 2026-01-01 | wc -l)" = 1 ] || { echo "--who matched a longer name"; fail=1; }
out=$(bash src/remind.sh --who 2>/dev/null); rc=$?; [ $rc = 2 ] && [ -z "$out" ] || { echo "--who without a name should print nothing and exit 2"; fail=1; }
out=$(BOOKINGS=$t bash src/remind.sh --who nobody 2026-01-01); rc=$?; [ $rc = 0 ] && [ -z "$out" ] || { echo "--who with no match should print nothing and exit 0"; fail=1; }
rm -f "$t"; exit $fail
EOF
bash tools/check; echo "check exit $?"; bash tools/lint; echo "lint exit $?"; git status --short

